-- Resources content for weighted copy rotation (CLAUDE.md, "Resources stay in
-- step with the code"; docs/underwriting-traffic-redesign.md §13.2). Content
-- only; the schema change is 20261008120000_underwriting_copy_rotation_weights.sql.

select private.rc_release_guide(
  p_slug => 'underwriting-copy-and-placement',
  p_tool_key => 'underwriting',
  p_title => 'Copy, rotation, and placing a credit',
  p_summary => 'Link a contract''s messages, weight their rotation or dedicate one to a line where the order says so, then place a credit manually or let auto-fill do it.',
  p_screen_keys => array['underwriting.contract', 'underwriting.copy'],
  p_sort_order => 30,
  p_version_note => 'Messages can rotate in a ratio',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit needs approved copy behind it before it can run anywhere."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the contract's Copy tab, select "},{"type":"text","text":"+ New message","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Link existing…","marks":[{"type":"bold"}]},{"type":"text","text":" to attach a script. A draft message can be approved right from its card — only approved copy rotates or gets placed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy shared across more than one contract shows which others use it, right on its edit card."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rotation"}]},{"type":"paragraph","content":[{"type":"text","text":"Rotation is automatic: each contract cycles through its own linked messages in broadcast order, with nothing for staff to pick. An aired, frozen, or manager-overridden placement is a fixed point that rotation won't move."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rotation weights"}]},{"type":"paragraph","content":[{"type":"text","text":"By default every message on a contract airs equally often. When an order asks for one message to air more than another, open "},{"type":"text","text":"Rotation weight…","marks":[{"type":"bold"}]},{"type":"text","text":" from the message's menu and set a whole number from 1 to 20."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Messages rotate in proportion to their weights: a weight of 2 against 1 airs the first twice as often, spread through the run rather than in a block."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weights compare messages that rotate together: the contract's general messages, or the messages dedicated to one line. Only approved messages count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The card reads "},{"type":"text","text":"airs 2 of every 3 spots","marks":[{"type":"bold"}]},{"type":"text","text":" once the weights differ. Aired credits count toward the ratio, and changing a weight re-sequences only credits that have not aired."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A weight belongs to the message on this contract; the same message on another order keeps its own."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A message for one line"}]},{"type":"paragraph","content":[{"type":"text","text":"Some orders give a message to one line rather than to the whole contract — for example, “For Carpool: #1” and “For Total Program: #2”. When linking the message, choose the line under "},{"type":"text","text":"Use on","marks":[{"type":"bold"}]},{"type":"text","text":", or use "},{"type":"text","text":"Use on one line only…","marks":[{"type":"bold"}]},{"type":"text","text":" from a linked message's menu."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A message dedicated to a line airs only on that line."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"That line then airs only its own messages. If it has more than one, they rotate among themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every other line keeps rotating the contract's other messages, as before."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a revision replaces the line, the message's card shows "},{"type":"text","text":"Line replaced — set it again","marks":[{"type":"bold"}]},{"type":"text","text":"; choose the new line."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Placing a credit"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manually, from a schedule line's "},{"type":"text","text":"Place a credit","marks":[{"type":"bold"}]},{"type":"text","text":" link: pick an open break (grouped by period), confirm or change the suggested message (already the next one in rotation), and select "},{"type":"text","text":"Place credit","marks":[{"type":"bold"}]},{"type":"text","text":". Only messages that may air on that line are offered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Or let auto-fill do it: "},{"type":"text","text":"Auto-fill this line","marks":[{"type":"bold"}]},{"type":"text","text":" from a line's own menu, "},{"type":"text","text":"Auto-fill this contract","marks":[{"type":"bold"}]},{"type":"text","text":" for every line on one contract, or "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" for every active contract — the same placement path either way, just run in a loop."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A same-underwriter or same-industry adjacency warning is advisory on the manual placement form — it's shown, never blocked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-fill generates the rundowns it needs as it goes, so a fresh contract can be filled for its whole campaign in one click even before a rundown for those dates exists yet."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-08-underwriting-rotation-weights',
  p_tool_key => 'underwriting',
  p_released_on => '2026-10-08',
  p_title => 'Messages can rotate in a ratio',
  p_guide_slugs => array['underwriting-copy-and-placement'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A contract's messages can now rotate in a ratio. Every message still airs equally often unless you say otherwise; to give one message more spots than another, choose Rotation weight… from its menu on the contract's Copy tab and set a weight. A weight of 2 against 1 airs the first twice as often, and credits that have already aired are left alone."}]}]}$body$
);
